public class I {
    public static boolean DEBUG = true;
    public static String name = "I";

    public static void main(String[] args) throws IOException {
        FastScanner scanner;
        PrintWriter writer;
        if (DEBUG) {
            scanner = new FastScanner(System.in);
            writer = new PrintWriter(System.out);
        } else {
            scanner = new FastScanner(name + ".in");
            writer = new PrintWriter(new BufferedWriter(new FileWriter(name + ".out")));
        }

        float N = Float.parseFloat(scanner.nextString());
        float P = Float.parseFloat(scanner.nextString());

        int i = 0;
        do {
            double val = i * (i - 1) * (i - 2) / 6.0 + i * (i - 1) * (N - i) / 2.0 + i * (N - i) * (N - i - 1) / 4.0;
            val = val / (N * (N - 1) * (N - 2) / 6.0);
            if (val >= P) {
                writer.println(i);
                break;
            }
            i++;
        } while (i <= N);

        writer.close();
    }

    static class BIT {
        public int[] tree;

        public BIT(int len) {
            tree = new int[len + 5];
        }

        public void update(int index, int val) {
            index++;
            while (index < tree.length) {
                tree[index] ^= val;
                index += index & -index;
            }
        }

        public int query(int index) {
            int result = 0;
            index++;
            while (index > 0) {
                result ^= tree[index];
                index -= index & -index;
            }
            return result;
        }

        public int rangeSum(int low, int high) {
            return query(high) - query(low - 1);
        }
    }

