        tout = new int[adjList.length];
        BL = new int[adjList.length][log2(adjList.length) + 1];
        recur_bl(root, root);
    }

    public static void recur_bl(int v, int p) {
        tin[v] = ++ct;
        BL[v][0] = p;
        for (int i = 1; i <= log2(adjList.length); i++) {
            BL[v][i] = BL[BL[v][i - 1]][i - 1];
        }
        for (int neighbor : adjList[v]) {
            if (neighbor != p) {
                recur_bl(neighbor, v);
            }
        }
        tout[v] = ++ct;
    }

    public static boolean is_ancestor(int u, int v) {
        return tin[u] <= tin[v] && tout[u] >= tout[v];
    }

    public static int lca(int u, int v) {
        if (is_ancestor(u, v)) return u;
