#include <bits/stdc++.h>
using namespace std;

bool DEBUG = true;
string name = "I";

struct FastScanner {
    istream& dis;
    vector<char> buffer;
    size_t pointer;

    FastScanner(istream& is) : dis(is), buffer(1 << 17), pointer(0) {}

    int nextInt() {
        int ret = 0;
        char b;
        do {
            b = nextByte();
        } while (b <= ' ');
        bool negative = false;
        if (b == '-') {
            negative = true;
            b = nextByte();
        }
        while (b >= '0' && b <= '9') {
            ret = 10 * ret + (b - '0');
            b = nextByte();
        }
        return negative ? -ret : ret;
    }

    long long nextLong() {
        long long ret = 0;
        char b;
        do {
            b = nextByte();
        } while (b <= ' ');
        bool negative = false;
        if (b == '-') {
            negative = true;
            b = nextByte();
        }
        while (b >= '0' && b <= '9') {
            ret = 10 * ret + (b - '0');
            b = nextByte();
        }
        return negative ? -ret : ret;
    }

    char nextByte() {
        if (pointer == buffer.size()) {
            dis.read(&buffer[0], buffer.size());
            pointer = 0;
        }
        return buffer[pointer++];
    }

    string nextString() {
        string ret;
        char b;
        do {
            b = nextByte();
        } while (b <= ' ');
        while (b > ' ') {
            ret.push_back(b);
            b = nextByte();
        }
        return ret;
    }
};

int log2(int n) {
    return (int)ceil(log2(n));
}

struct BIT {
    vector<int> tree;
    BIT(int len) {
        tree.assign(len + 5, 0);
    }
    void update(int index, int val) {
        index++;
        while (index < (int)tree.size()) {
            tree[index] ^= val;
            index += index & -index;
        }
    }
    int query(int index) {
        int result = 0;
        index++;
        while (index > 0) {
            result ^= tree[index];
            index -= index & -index;
        }
        return result;
    }
    int rangeSum(int low, int high) {
        return query(high) ^ query(low - 1);
    }
}

vector<vector<int>> adjList;
vector<int> tin, tout;
vector<vector<int>> BL;
int ct;

void recur_bl(int v, int p) {
    tin[v] = ++ct;
    BL[v][0] = p;
    for (int i = 1; i <= log2((int)adjList.size()); i++) {
        BL[v][i] = BL[BL[v][i - 1]][i - 1];
    }
    for (int neighbor : adjList[v]) {
        if (neighbor != p) {
            recur_bl(neighbor, v);
        }
    }
    tout[v] = ++ct;
}

void preprocess(int root) {
    ct = 0;
    int n = (int)adjList.size();
    tin.assign(n, 0);
    tout.assign(n, 0);
    int maxLog = log2(n);
    BL.assign(n, vector<int>(maxLog + 1));
    recur_bl(root, root);
}

bool is_ancestor(int u, int v) {
    return tin[u] <= tin[v] && tout[u] >= tout[v];
}

int lca(int u, int v) {
    if (is_ancestor(u, v))
        return u;
    if (is_ancestor(v, u))
        return v;
    for (int i = log2((int)adjList.size()); i >= 0; i--) {
        if (!is_ancestor(BL[u][i], v))
            u = BL[u][i];
    }
    return BL[u][0];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    FastScanner scanner(cin);
    ostream& writer = cout;

    float N_float = stof(scanner.nextString());
    float P = stof(scanner.nextString());
    int N = (int)N_float;

    int i = 0;
    do {
        double val = i * (i - 1) * (i - 2) / 6.0 + i * (i - 1) * (N - i) / 2.0 + i * (N - i) * (N - i - 1) / 4.0;
        val = val / (N * (N - 1) * (N - 2) / 6.0);
        if (val >= P) {
            writer << i << "\n";
            break;
        }
        i++;
    } while (i <= N);
    return 0;
}

